'use strict';
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage = {
    get(key) { try { return localStorage.getItem(key); } catch { return null; } },
    set(key,value) { try { localStorage.setItem(key,value); } catch { /* Preferences still work for this visit. */ } },
    remove(key) { try { localStorage.removeItem(key); } catch { /* No persistent session to clear. */ } },
};
let scoutQuery = '', scoutFilter = 'all';
let token = storage.get('frc_token'), user = null, league = null, registerMode = false, refreshTimer, routeSerial = 0;
try { user = JSON.parse(storage.get('frc_user')); } catch { /* invalid stored session */ }
const draftLabel = status => ({PRE_DRAFT:'PRE DRAFT',ACTIVE:'DRAFT LIVE',COMPLETED:'DRAFT COMPLETE'}[status] || status);
const tabs = [['home','League home'],['team','My team'],['draft','Draft room'],['players','FRC teams'],['matchups','Matchups'],['standings','Standings'],['transactions','Transactions'],['scoring','Scoring & rules']];
const catalog = [[254,'The Cheesy Poofs'],[1678,'Citrus Circuits'],[1690,'Orbit'],[4414,'HighTide'],[1114,'Simbotics'],[2056,'OP Robotics'],[148,'Robowranglers'],[118,'Robonauts'],[1323,'MadTown Robotics'],[973,'Greybots'],[2910,'Jack in the Bot'],[6328,'Mechanical Advantage']];
const themes = [
    {id:'default',name:'Fantasy FRC',colors:['#f4bb38','#101216','#f5f6f8'],description:'Gold · charcoal'},
    {id:'light',name:'Light',colors:['#ffffff','#885b00','#152034'],description:'White · warm gold'},
    {id:'citrus',name:'1678 · Citrus Circuits',colors:['#80c342','#171e27','#ffffff'],description:'Citrus green · dark navy · white'},
    {id:'poofs',name:'254 · The Cheesy Poofs',colors:['#0070ff','#232323','#ffffff'],description:'Royal blue · black · white'},
    {id:'orbit',name:'1690 · Orbit',colors:['#0000cc','#ffffff','#141430'],description:'Deep blue · white'},
    {id:'hightide',name:'4414 · HighTide',colors:['#51b3b0','#1b4652','#000000'],description:'Teal · deep ocean · black'},
];
function renderThemes() {
    $('themes').innerHTML=themes.map(t=>{
        const selected=document.documentElement.dataset.theme===t.id;
        const team=t.name.includes(' · ')?t.name.split(' · ')[0]:'FRC';
        return `<button type="button" class="theme-choice" data-action="theme" data-theme-choice="${t.id}" aria-pressed="${selected}"><span class="theme-preview" data-palette="${t.id}" aria-hidden="true"><span class="preview-sidebar"><i></i><i></i><i></i></span><span class="preview-canvas"><span class="preview-topline"><b>${team}</b><i></i></span><span class="preview-lines"><i></i><i></i></span><span class="preview-chart"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></span></span><span class="preview-orbit"></span></span><span class="theme-label"><strong>${t.name}</strong><span class="theme-check" aria-hidden="true">✓</span></span><span class="theme-description">${t.description}</span><span class="theme-state">${selected?'Selected':'Choose palette'}</span></button>`;
    }).join('');
}
function updateThemeSelection() {
    for (const control of document.querySelectorAll('[data-theme-choice]')) {
        const selected=control.dataset.themeChoice===document.documentElement.dataset.theme;
        control.setAttribute('aria-pressed',String(selected));
        control.querySelector('.theme-state').textContent=selected?'Selected':'Choose palette';
    }
}
const metricLabels = {auto:'Autonomous production',teleop:'Teleop production',endgame:'Endgame contribution',cycles:'Completed scoring cycles',win:'Win / tie bonus',fouls:'Foul penalty units'};
const button = (text, action, attrs='', style='ghost small') => `<button class="${style}" data-action="${action}" ${attrs}>${text}</button>`;
const empty = (title, text) => `<div class="empty"><div class="empty-symbol">◇</div><h2>${title}</h2><p class="muted">${text}</p></div>`;
const time = value => new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const mine = () => league.rosters.find(r => r.id === league.my_roster_id);
const owner = () => league.owner_id === user.user_id;
const rosterName = id => esc(league.rosters.find(r=>r.id===id)?.name || 'Manager');
const locked = () => league.periods.some(p=>p.status==='OPEN') || (league.periods.length>0 && league.periods.every(p=>p.status==='FINAL'));
const teamName = number => esc(catalog.find(t=>t[0]===number)?.[1] || 'FRC team · manually entered');
function notify(message, error=false) { $('notice').textContent=message; $('notice').className=error?'error':''; $('notice').hidden=false; clearTimeout(notify.timer); notify.timer=setTimeout(()=>$('notice').hidden=true,error?12000:5500); }
async function api(path, body, method='POST') {
    const requestToken=token;
    const response = await fetch(path,{method:body===undefined?'GET':method,headers:{...(requestToken?{Authorization:`Bearer ${requestToken}`} : {}),...(body!==undefined?{'Content-Type':'application/json'}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});
    const data = await response.json();
    if (response.status===401 && requestToken && requestToken===token) { logout(); throw new Error('Your session expired. Please sign in again.'); }
    if (!response.ok) throw new Error(Array.isArray(data.detail)?data.detail.map(x=>`${x.loc.at(-1)}: ${x.msg}`).join('; '):data.detail || 'Request failed');
    return data;
}
function logout() { clearInterval(refreshTimer);if($('modal').open)closeModal();token=null;user=null;league=null;storage.remove('frc_token');storage.remove('frc_user');location.hash='leagues';route(); }
function signedIn(data) { clearTimeout(notify.timer);$('notice').hidden=true;token=data.access_token;user={username:data.username,user_id:data.user_id,is_admin:!!data.is_admin};storage.set('frc_token',token);storage.set('frc_user',JSON.stringify(user));$('password').value='';route(); }
function theme(name) {
    const selected=themes.some(t=>t.id===name)?name:'default';
    document.documentElement.dataset.theme=selected;storage.set('frc_theme',selected);
    const meta=document.querySelector('meta[name="theme-color"]');
    if(meta)meta.content=({default:'#101216',light:'#f5f6fa',citrus:'#0c1015',poofs:'#101318',orbit:'#f3f4fa',hightide:'#0b171c'})[selected];
}
function showModal(title, html) { $('modalTitle').textContent=title;$('modalBody').innerHTML=html+'<p class="dialog-status error" role="status" id="dialogStatus"></p>';$('modal').showModal(); }
function closeModal() { $('modal').close(); }
function leaguePath(tab='home') { return `#league/${league.id}/${tab}`; }
function formValue(form,name) { return new FormData(form).get(name); }
function field(name,label,type='text',value='',extra='') { return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`; }
function option(value,label,selected=false) { return `<option value="${esc(value)}" ${selected?'selected':''}>${esc(label)}</option>`; }
function select(name,label,options) { return `<label>${label}<select name="${name}">${options}</select></label>`; }
function activity(items) { return items.length?items.map(a=>`<div class="activity"><span class="tag">${esc(a.kind)}</span> ${esc(a.text)}<time datetime="${esc(a.at)}">${time(a.at)}</time></div>`).join(''):'<p class="muted">League activity will appear here.</p>'; }
async function route() {
    clearInterval(refreshTimer);if($('modal').open)closeModal();const serial=++routeSerial;
    for(const id of ['gate','dashboard','league','profile','admin']) $(id).hidden=true;
    $('profileButton').hidden=$('logoutButton').hidden=!(token&&user);
    $('adminButton').hidden=!(token&&user?.is_admin);
    if(!token||!user) { $('gate').hidden=false;return; }
    const parts=location.hash.replace('#','').split('/');
    if(parts[0]==='profile') { $('profile').hidden=false;$('profileUser').textContent=`Signed in as ${user.username}${user.is_admin?' · Administrator':''}`;renderThemes();return; }
    try {
        if(parts[0]==='admin') {
            $('admin').hidden=false;$('admin').innerHTML='<div class="page-loading">Loading administration…</div>';
            const data=await api('/api/admin/overview');if(serial!==routeSerial)return;
            $('admin').innerHTML=`<p class="eyebrow">SITE ADMINISTRATION</p><h1>Administration</h1><div class="stat-grid"><div class="stat"><strong>${data.users.length}</strong><span>Accounts</span></div><div class="stat"><strong>${data.leagues.length}</strong><span>Leagues</span></div></div><div class="panel"><h2>Accounts</h2><div class="table-wrap"><table><thead><tr><th>Username</th><th>Role</th></tr></thead><tbody>${data.users.map(u=>`<tr><td>${esc(u.username)}</td><td>${u.is_admin?'Administrator':'Manager'}</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><h2>Leagues</h2>${data.leagues.length?`<div class="table-wrap"><table><thead><tr><th>League</th><th>Commissioner</th><th>Managers</th><th>Draft</th></tr></thead><tbody>${data.leagues.map(l=>`<tr><td>${esc(l.name)}</td><td>${esc(l.commissioner)}</td><td>${l.member_count}</td><td>${esc(draftLabel(l.draft_status))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No leagues yet.</p>'}</div>`;
        } else if(parts[0]==='league'&&/^\d+$/.test(parts[1])) {
            $('league').hidden=false;$('leagueContent').innerHTML='<div class="page-loading">Loading your league…</div>';
            const data=await api(`/api/leagues/${parts[1]}`);if(serial!==routeSerial)return;league=data;renderLeague(parts[2]||'home');
            if(parts[2]==='draft') {
                let refreshInFlight=false;
                refreshTimer=setInterval(async()=>{
                    if(document.hidden||$('modal').open||refreshInFlight)return;
                    refreshInFlight=true;
                    try {
                        const d=await api(`/api/leagues/${parts[1]}`);
                        if(serial!==routeSerial)return;
                        if(d.draft.current_pick_index===league.draft.current_pick_index&&d.draft.status===league.draft.status&&d.member_count===league.member_count){league=d;return;}
                        const pickField=document.querySelector('[data-form="pick"] input[name="team_number"]');
                        const draftInput=pickField?.value,draftFocused=document.activeElement===pickField;
                        league=d;renderLeague('draft');
                        const freshField=document.querySelector('[data-form="pick"] input[name="team_number"]');
                        if(freshField&&draftInput&&d.draft.current_picker_id===user.user_id){freshField.value=draftInput;if(draftFocused)freshField.focus();}
                    } catch(error) {
                        if(serial===routeSerial){clearInterval(refreshTimer);notify(error.message,true);}
                    } finally {refreshInFlight=false;}
                },7000);
            }
        } else { $('dashboard').hidden=false;$('dashboard').innerHTML='<div class="page-loading">Loading your leagues…</div>';const data=await api('/api/leagues');if(serial!==routeSerial)return;renderDashboard(data); }
    } catch(error) { if(serial!==routeSerial)return;const target=parts[0]==='admin'?'admin':parts[0]==='league'?'leagueContent':'dashboard';$(target).innerHTML=empty('Couldn’t load this page',esc(error.message))+'<a href="#leagues" class="button ghost">My leagues</a>';notify(error.message,true); }
}
function renderDashboard(leagues) {
    $('dashboard').innerHTML=`<div class="section-head"><div><p class="eyebrow">LEAGUE HEADQUARTERS</p><h1>Good to have you back, ${esc(user.username)}.</h1><p class="lead">Your leagues. Your lineups. Your next winning move.</p></div><div class="row">${button('Join a league','join','','ghost')}${button('+ Create league','create','','primary')}</div></div><div class="banner"><strong>BIOCORE preseason</strong> · Draft and organize your league now. Production, cycle, and bonus scoring templates stay provisional until your commissioner activates the season configuration.</div><div class="row between"><h2>My leagues <span class="muted">${leagues.length}</span></h2><span class="muted">Private leagues · Invite code required</span></div>${leagues.length?`<div class="grid">${leagues.map(l=>`<article class="panel league-card"><div class="row between"><span class="tag">${esc(draftLabel(l.draft_status))}</span><span class="muted">${l.member_count} / ${l.max_teams} managers</span></div><h2>${esc(l.name)}</h2><p class="muted">${esc(l.my_team_name)}<br>${l.starter_count} starters · ${l.roster_size-l.starter_count} bench · ${l.regular_weeks} periods</p><a class="button ghost full" href="#league/${l.id}/home">Open league <span aria-hidden="true">→</span></a></article>`).join('')}</div>`:`<div class="panel">${empty('Your first league starts here','Create a private league and invite your friends, or enter a code from your commissioner.')}</div>`}`;
}
function renderLeague(tab) {
    if((!tabs.some(t=>t[0]===tab)&&tab!=='commissioner')||(tab==='commissioner'&&!owner()))tab='home';
    $('leagueHeading').innerHTML=`<a class="muted" href="#leagues">← My leagues</a><div class="section-head"><div><p class="eyebrow" style="margin-top:24px">${esc(draftLabel(league.draft_status))} · ${league.member_count} MANAGERS</p><h1>${esc(league.name)}</h1><p class="muted">${esc(league.my_team_name)} · ${owner()?'Commissioner':'Manager'}</p></div><div class="row">${button('Invite friends','invite','','ghost')}${button('↻ Refresh','refresh','','ghost')}</div></div>`;
    $('leagueTabs').innerHTML=[...tabs,...(owner()?[['commissioner','Commissioner']]:[])].map(([key,text])=>`<a href="${leaguePath(key)}" ${tab===key?'aria-current="page"':''}>${text}</a>`).join('');
    const views={home:homeView,team:teamView,draft:draftView,players:playersView,matchups:matchupsView,standings:standingsView,transactions:transactionsView,scoring:scoringView,commissioner:commissionerView};
    $('leagueContent').innerHTML=views[tab]();
}
function homeView() {
    const r=mine(), rank=league.standings.find(x=>x.roster_id===r.id), current=league.periods.find(p=>p.status!=='FINAL')||league.periods.at(-1);
    const matchup=current&&league.matchups.find(m=>m.week===current.week&&(m.a===r.id||m.b===r.id));
    const finals=league.matchups.filter(m=>m.final&&m.week>league.regular_weeks);const championship=finals.find(m=>league.periods.find(p=>p.week===m.week)?.kind==='FINAL');
    let seasonBanner='';
    if(championship){const a=league.standings.find(s=>s.roster_id===championship.a),b=league.standings.find(s=>s.roster_id===championship.b);const winner=championship.a_score>championship.b_score||championship.a_score===championship.b_score&&a.rank<b.rank?championship.a:championship.b;seasonBanner=`<div class="banner"><strong>League champion: ${rosterName(winner)}</strong> · The season is complete.</div>`;}
    else if(league.periods.length&&league.periods.every(p=>p.status==='FINAL'))seasonBanner=`<div class="banner"><strong>Season complete · ${esc(league.standings[0].name)} finishes first.</strong></div>`;
    return `${seasonBanner}${!league.scoring_active?'<div class="banner"><strong>Kickoff preparation</strong> · Fantasy rules are provisional. Review the scoring page, then have your commissioner configure and activate the season before opening period 1.</div>':''}<div class="stat-grid"><div class="stat"><strong>${rank.wins}–${rank.losses}–${rank.ties}</strong><span>Win · loss · tie</span></div><div class="stat"><strong>#${rank.rank}</strong><span>League standing</span></div><div class="stat"><strong>${rank.points_for.toFixed(2)}</strong><span>Finalized fantasy points</span></div><div class="stat"><strong>${r.teams.length} / ${league.roster_size}</strong><span>Roster spots filled</span></div></div><div class="layout"><div class="stack"><div class="panel"><div class="row between"><h2>${current?`Period ${current.week} · ${esc(current.kind.toLowerCase())}`:'Up next: draft your alliance'}</h2><span class="tag">${current?esc(current.status):'PRESEASON'}</span></div>${matchup?matchupCard(matchup):empty(current?'A bye on your schedule':'Your roster is waiting',current?'No head-to-head matchup this period. Lineup locks still apply.':'Once everyone joins, your commissioner can start the snake draft.')}<a class="button ghost full" href="${leaguePath(current?'team':'draft')}">${current?'Manage my lineup':'Go to draft room'}</a></div><div class="panel"><h2>League clubhouse</h2><p class="muted">Talk strategy, announce changes, and keep your league in the loop.</p><form data-form="message"><label class="sr-only" for="clubMessage">League message</label><textarea id="clubMessage" name="text" maxlength="1000" required placeholder="Write to your league…"></textarea><button class="primary" style="margin-top:12px">Post message</button></form>${activity(league.activity.filter(a=>a.kind==='MESSAGE').slice(0,8))}</div></div><div class="stack"><div class="panel"><h2>Your next move</h2><p class="muted">${league.draft_status==='PRE_DRAFT'?'Invite your managers, customize your team name, and review scoring rules.':league.draft_status==='ACTIVE'?'The draft is underway. Check the board and make your pick when you’re on the clock.':locked()?'Your lineup is frozen. Follow the current matchup while your commissioner imports results.':'Set your starters, scout free agents, or make a trade before the next period opens.'}</p><a class="button primary full" href="${leaguePath(league.draft_status==='ACTIVE'?'draft':'team')}">${league.draft_status==='ACTIVE'?'Enter draft room':'Open my team'}</a></div><div class="panel"><h2>Recent activity</h2>${activity(league.activity.filter(a=>a.kind!=='MESSAGE').slice(0,7))}</div></div></div>`;
}
function teamView() {
    const r=mine();return `<div class="section-head"><div><p class="eyebrow">MY TEAM</p><h2>${esc(r.name)}</h2><p class="muted">${league.starter_count} starter slots · ${league.roster_size-league.starter_count} bench slots · Waiver priority #${r.waiver_priority}</p></div>${button('Rename team','rename','','ghost')}</div>${locked()?'<div class="banner">Lineups and transactions are locked during an open scoring period and after the season ends.</div>':''}<div class="layout"><div class="panel"><h2>Set your lineup</h2><p class="muted">Only starters score. Lineups freeze when the commissioner opens a period. Empty slots score zero.</p>${r.teams.length?`<form data-form="lineup">${r.teams.map(t=>`<div class="robot"><div><strong class="number">${t.number}</strong><div class="muted">${teamName(t.number)}</div></div><label class="check"><input name="starters" aria-label="Start FRC ${t.number}" type="checkbox" value="${t.number}" ${t.position==='STARTER'?'checked':''} ${locked()?'disabled':''}>Starter</label></div>`).join('')}<button class="primary full" ${locked()?'disabled':''}>Save lineup</button></form>`:empty('No FRC teams yet','Your draft picks will appear here.')}<a class="button ghost full" href="${leaguePath(league.draft_status==='COMPLETED'?'players':'draft')}">${league.draft_status==='COMPLETED'?'Scout available teams':'Open draft room'}</a></div><div class="stack"><div class="panel"><h2>Watchlist</h2>${r.watchlist.length?r.watchlist.map(n=>`<div class="robot"><div><span class="number">${n}</span><div class="muted">${teamName(n)}</div></div>${button('Remove','watch',`data-number="${n}"`)}</div>`).join(''):'<p class="muted">Save teams from the FRC teams page to plan your next pick or waiver claim.</p>'}</div><div class="panel"><h2>Roster moves</h2><p class="muted">Add teams through rolling-priority waivers. Trades exchange one robot for one robot. Moves are available between scoring periods.</p>${r.teams.map(t=>`<div class="row between robot"><span class="number">${t.number}</span>${button('Drop team','drop',`data-number="${t.number}" ${locked()||league.draft_status!=='COMPLETED'?'disabled':''}`)}</div>`).join('')}<a href="${leaguePath('transactions')}" class="button ghost full">Trades & waivers</a></div></div></div>`;
}
function draftView() {
    const d=league.draft, turn=d.current_picker_id===user.user_id;
    return `<div class="banner"><strong>Snake draft</strong> · Random first-round order, reversed each round. ${league.roster_size} rounds · ${league.member_count*league.roster_size} picks · One FRC team per roster across the league.</div><div class="layout"><div class="stack"><div class="panel"><p class="eyebrow">${d.status==='ACTIVE'?'ON THE CLOCK':esc(d.status.replaceAll('_',' '))}</p><h2>${d.status==='ACTIVE'?esc(d.current_picker_name):d.status==='COMPLETED'?'Your alliances are locked in.':'Get your managers together.'}</h2><p class="muted">${d.status==='ACTIVE'?`Pick ${d.current_pick_index+1} of ${d.total_picks} · Round ${Math.floor(d.current_pick_index/league.member_count)+1}. Board refreshes every 7 seconds.`:d.status==='COMPLETED'?'The schedule is ready. Set lineups before the first period opens.':`${league.member_count} of ${league.max_teams} managers joined. The commissioner can start with at least ${Math.max(2,league.playoff_teams)} managers.`}</p>${d.status==='PRE_DRAFT'&&owner()?button('Start snake draft','start-draft','','primary'):''}${d.status==='ACTIVE'?`<form data-form="pick" class="inline-form">${field('team_number',turn?'Your pick · FRC team number':'Waiting for the current manager','number','','min="1" max="999999" required '+(turn?'':'disabled'))}<button class="primary" ${turn?'':'disabled'}>Draft team</button></form><a href="${leaguePath('players')}">Scout teams →</a>`:''}${d.status==='COMPLETED'?`<a href="${leaguePath('team')}" class="button primary">Manage my team</a>`:''}${d.status==='ACTIVE'&&owner()&&!turn?`<form data-form="proxy-pick" class="inline-form">${field('team_number','Commissioner proxy pick for current manager','number','','min="1" max="999999" required')}<button class="ghost">Submit proxy pick</button></form><p class="muted">For an absent manager: this action is recorded in the league draft log.</p>`:''}</div><div class="panel"><h2>Draft board</h2>${d.sequence.length?`<div class="draft-board">${d.sequence.map((uid,i)=>`<div class="draft-cell ${i===d.current_pick_index&&d.status==='ACTIVE'?'on-clock':''}"><small>R${Math.floor(i/league.member_count)+1} · Pick ${i+1}</small>${esc(league.rosters.find(r=>r.user_id===uid)?.name||'Manager')}<small>${i<d.current_pick_index?'Picked':i===d.current_pick_index&&d.status==='ACTIVE'?'On clock':'Upcoming'}</small></div>`).join('')}</div>`:'<p class="muted">The order is randomized when the commissioner starts the draft.</p>'}</div></div><div class="panel"><h2>Draft activity</h2>${activity(league.activity.filter(a=>a.kind==='DRAFT').slice(0,30))}<h3 style="margin-top:24px">Manager rosters</h3>${league.rosters.map(r=>`<div class="activity"><strong>${esc(r.name)}</strong><div class="muted">${r.teams.map(t=>t.number).join(' · ')||'No picks yet'}</div></div>`).join('')}</div></div>`;
}
function playersView() {
    return `<div class="section-head"><div><p class="eyebrow">SCOUTING DESK</p><h2>Find your next difference-maker.</h2><p class="muted">Starter directory, not rankings. Search a team name or enter any FRC number. Additional numbers are manually entered; verify eligibility with your commissioner.</p></div></div><form data-form="search" class="inline-form searchbar">${field('search','Search FRC teams','search',scoutQuery,'placeholder="254 or Cheesy Poofs"')}<label>Availability<select name="filter">${option('all','All teams',scoutFilter==='all')}${option('free','Available teams',scoutFilter==='free')}${option('watch','My watchlist',scoutFilter==='watch')}</select></label><button class="primary">Search</button></form><div class="panel" id="playerResults">${playerRows(scoutTeams())}</div>`;
}
function scoutTeams() {
    const pool=new Map(catalog);
    for(const n of [...mine().watchlist,...league.rosters.flatMap(r=>r.teams.map(t=>t.number))])if(!pool.has(n))pool.set(n,'Manually entered FRC team');
    if(/^\d+$/.test(scoutQuery)&&Number(scoutQuery)>0&&Number(scoutQuery)<=999999&&!pool.has(Number(scoutQuery)))pool.set(Number(scoutQuery),'Manually entered FRC team');
    return [...pool].filter(([n,name])=>(String(n).includes(scoutQuery)||name.toLowerCase().includes(scoutQuery))&&(scoutFilter!=='free'||!league.rosters.some(r=>r.teams.some(t=>t.number===n)))&&(scoutFilter!=='watch'||mine().watchlist.includes(n)));
}
function playerRows(teams) {
    if(!teams.length)return empty('No teams found','Try a team number, a different name, or another availability filter.');
    return teams.map(([n,name])=>{const r=league.rosters.find(r=>r.teams.some(t=>t.number===n));const canDraft=league.draft_status==='ACTIVE'&&league.draft.current_picker_id===user.user_id&&!r;const canClaim=league.draft_status==='COMPLETED'&&!locked()&&!r;return `<div class="robot"><div><strong class="number">${n}</strong> <strong>${esc(name)}</strong><div class="muted">${r?esc(r.name):'Available'} · Imported scores in Matchups · No projections</div></div><div class="row">${button(mine().watchlist.includes(n)?'★ Saved':'☆ Watch','watch',`data-number="${n}"`)}${canDraft?button('Draft','pick-team',`data-number="${n}"`,'primary small'):canClaim?button('Claim','claim',`data-number="${n}"`,'primary small'):''}</div></div>`;}).join('');
}
function matchupCard(m) {
    return `<div class="vs"><div><strong>${rosterName(m.a)}</strong><div class="score">${m.a_score.toFixed(2)}</div></div><span class="versus">VS</span><div><strong>${rosterName(m.b)}</strong><div class="score">${m.b_score.toFixed(2)}</div></div></div><p class="muted">${m.final?'Final result':'Provisional · awaiting finalized results'}</p>`;
}
function matchupsView() {
    if(!league.periods.length)return `<div class="panel">${empty('Your schedule arrives after the draft','Round-robin regular-season matchups are generated automatically. Odd manager counts include byes.')}</div>`;
    return `<div class="section-head"><div><h2>Every period. Every matchup.</h2><p class="muted">A period is your league’s scoring window, managed by the commissioner. Only frozen starters contribute.</p></div></div><div class="grid two">${league.periods.map(p=>`<div class="panel"><div class="row between"><h2>Period ${p.week} · ${esc(p.kind.toLowerCase())}</h2><span class="tag">${esc(p.status)}</span></div>${league.matchups.filter(m=>m.week===p.week).map(matchupCard).join('')}<p class="muted">${league.rosters.filter(r=>!league.matchups.some(m=>m.week===p.week&&(m.a===r.id||m.b===r.id))).map(r=>esc(r.name)+' has a bye.').join(' ')}</p>${button('View robot score breakdown','score-detail',`data-week="${p.week}"`)}</div>`).join('')}</div>`;
}
function standingsView() {
    return `<div class="panel"><h2>League standings</h2><p class="muted">Regular season only. Ranked by wins + half of ties, then points for, then original join order. ${league.playoff_teams?'Top four advance. Playoff ties go to the higher regular-season seed.':'No playoffs; the final regular-season leader wins.'} Bye periods don’t count toward records.</p><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Fantasy team</th><th>W</th><th>L</th><th>T</th><th>Points for</th><th>Points against</th></tr></thead><tbody>${league.standings.map(r=>`<tr class="${r.roster_id===league.my_roster_id?'mine':''}"><td class="number">${r.rank}</td><td>${esc(r.name)} ${r.roster_id===league.my_roster_id?'<span class="tag">YOU</span>':''}</td><td>${r.wins}</td><td>${r.losses}</td><td>${r.ties}</td><td>${r.points_for.toFixed(2)}</td><td>${r.points_against.toFixed(2)}</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><h2>Managers & rosters</h2><div class="grid two">${league.rosters.map(r=>`<div><h3>${esc(r.name)}</h3><p class="muted">${esc(r.manager)} · Waiver #${r.waiver_priority}</p>${r.teams.map(t=>`<div class="rule-row"><span class="number">${t.number}</span><span class="muted">${esc(t.position)}</span></div>`).join('')||'<p class="muted">No FRC teams yet.</p>'}</div>`).join('')}</div></div>`;
}
function transactionsView() {
    const trades=league.trades.filter(t=>t.sender_id===league.my_roster_id||t.receiver_id===league.my_roster_id);
    return `<div class="section-head"><div><h2>Make your next move.</h2><p class="muted">Rolling-priority waivers, one-for-one trades, and a league-wide transaction log.</p></div>${button('Propose trade','trade',locked()||league.draft_status!=='COMPLETED'?'disabled':'','primary')}</div><div class="grid two"><div class="panel"><h2>My waiver claims</h2><p class="muted">Your priority: #${mine().waiver_priority}. Commissioner processes claims between periods. A successful claim moves you to the back. Claims from the same manager run in submission order.</p>${league.claims.map(c=>`<div class="activity"><strong>Add ${esc(c.add_key)}${c.drop_key?` / Drop ${esc(c.drop_key)}`:''}</strong><div class="row between"><span class="tag">${esc(c.status)}</span>${c.status==='PENDING'?button('Cancel','cancel-claim',`data-id="${c.id}"`):''}</div></div>`).join('')||'<p class="muted">No claims yet. Find a team on the FRC teams page.</p>'}<a class="button ghost full" href="${leaguePath('players')}">Find available FRC teams</a></div><div class="panel"><h2>My trade offers</h2>${trades.map(t=>`<div class="activity"><strong>${rosterName(t.sender_id)} → ${rosterName(t.receiver_id)}</strong><p class="muted">${esc(t.give_key)} for ${esc(t.receive_key)}</p><div class="row"><span class="tag">${esc(t.status)}</span>${t.status==='PENDING'?(t.receiver_id===league.my_roster_id?button('Accept','trade-decision',`data-id="${t.id}" data-decision="accept" ${locked()?'disabled':''}`)+button('Decline','trade-decision',`data-id="${t.id}" data-decision="decline"`):button('Cancel','trade-decision',`data-id="${t.id}" data-decision="cancel"`)):''}</div></div>`).join('')||'<p class="muted">No offers yet. Propose a trade to another manager after the draft.</p>'}</div></div><div class="panel"><h2>League transaction log</h2>${activity(league.activity.filter(a=>a.kind!=='MESSAGE'))}</div>`;
}
function scoringView() {
    const s=league.scoring;return `<div class="banner"><strong>${league.scoring_active?'Season rules activated':'Provisional BIOCORE template'}</strong> · Version ${esc(s.version)}. ${league.scoring_active?'These are commissioner-approved league rules.':'These weights and metric names are placeholders, not official BIOCORE scoring. Activate only after kickoff mapping is reviewed.'}</div><div class="layout"><div class="panel"><p class="eyebrow">FANTASY SCORING</p><h2>Every contribution has a value.</h2><p class="muted">Robot match points = Σ(metric × weight). ${s.aggregation==='average'?'Average each starter’s played-match points in the period':'Sum each starter’s played-match points in the period'}, then add your starters together. Bench teams score zero. No recorded match means zero.</p>${Object.entries(s.weights).map(([key,value])=>`<div class="rule-row"><span>${metricLabels[key]||esc(key)}</span><strong class="number">${value>0?'+':''}${value} / unit</strong></div>`).join('')}<p class="muted" style="margin-top:20px">Win units: 1 for a win, 0.5 for a tie, 0 for a loss. Fouls are positive penalty units with a negative weight. Production and cycles must be robot-attributed. Alliance points are never divided by three and treated as individual production.</p></div><div class="stack"><div class="panel"><h2>Your PPR equivalent</h2><p class="muted"><strong>Standard:</strong> production, endgame, win bonus, and foul deductions.<br><strong>Half PPR:</strong> add 0.5 points per completed scoring cycle.<br><strong>Full PPR:</strong> add 1 point per cycle.<br>Commissioners can customize all six weights before the season opens.</p></div><div class="panel"><h2>Fair-play rules</h2><p class="muted">Lineups and transactions lock when a period opens. Only that period’s starter snapshot counts. Match imports are deduplicated by match and robot; corrections replace earlier records until finalization. Final scores cannot be edited. Rules freeze when the first period opens.</p></div><div class="panel"><h2>Kickoff integration</h2><p class="muted">Use the normalized JSON import in commissioner tools. Map the released game’s robot-level fields to the six metrics, set a new rules version, choose sum or average, and activate. See KICKOFF.md in the project for the adapter contract.</p></div></div></div>`;
}
function commissionerView() {
    if(!owner())return empty('Commissioner tools','Only the league commissioner can manage season operations.');
    const frozen=league.periods.some(p=>p.status!=='SCHEDULED'),s=league.scoring;
    return `<div class="banner"><strong>Season operations</strong> · Review scoring at kickoff → complete draft → open period → import robot results → finalize → process waivers → open next period.</div><div class="layout"><div class="stack"><div class="panel"><h2>Scoring configuration</h2><p class="muted">Rules freeze after the first period opens. Choose your version and review every weight before activating.</p><form data-form="scoring"><fieldset ${frozen?'disabled':''} style="border:0;padding:0;margin:0">${field('version','Rules version','text',s.version,'required maxlength="80"')}${select('aggregation','Period aggregation',option('average','Average per played match',s.aggregation==='average')+option('sum','Sum of played matches',s.aggregation==='sum'))}<div class="form-grid">${Object.entries(s.weights).map(([k,v])=>field(k,metricLabels[k],'number',v,'required step="0.1" min="-100" max="100"')).join('')}</div><label class="check"><input type="checkbox" name="active" ${league.scoring_active?'checked':''}>I reviewed the season mapping. Activate these rules.</label><button class="primary full">Save scoring rules</button></fieldset></form>${frozen?'<p class="muted">Scoring is frozen for this season.</p>':''}</div><div class="panel"><h2>Period controls</h2><p class="muted">Opening immediately freezes starter lineups and blocks transactions. Finalization is permanent. Review imported records before finalizing, including any robots with no match data.</p>${league.periods.map(p=>`<div class="robot"><div><strong>Period ${p.week}</strong><div class="muted">${esc(p.kind)} · ${esc(p.status)}</div></div><div class="row">${p.status==='SCHEDULED'?button('Open period','open-period',`data-week="${p.week}"`):p.status==='OPEN'?button('Import JSON','import',`data-week="${p.week}"`,'primary small')+button('Finalize','finalize',`data-week="${p.week}"`):'<span class="tag">FINAL</span>'}</div></div>`).join('')||'<p class="muted">Complete the draft to generate the schedule.</p>'}</div></div><div class="stack"><div class="panel"><h2>League setup</h2><div class="rule-row"><span>Managers</span><strong>${league.member_count} / ${league.max_teams}</strong></div><div class="rule-row"><span>Roster</span><strong>${league.starter_count} starters + ${league.roster_size-league.starter_count} bench</strong></div><div class="rule-row"><span>Season</span><strong>${league.regular_weeks} regular periods</strong></div><div class="rule-row"><span>Playoffs</span><strong>${league.playoff_teams?'4 managers · 2 rounds':'Disabled'}</strong></div>${league.draft_status==='PRE_DRAFT'?button('Start snake draft','start-draft','','primary full'):''}</div><div class="panel"><h2>Waiver processing</h2><p class="muted">Claims resolve using current rolling priority. Conflicts and invalid drops fail without changing rosters. Results appear in the transaction log.</p>${button('Process pending claims','process-waivers',locked()||league.draft_status!=='COMPLETED'?'disabled':'','ghost full')}</div><div class="panel"><h2>Invite code</h2><p class="code">${esc(league.invite_code)}</p><p class="muted">Rotating invalidates the old invite immediately.</p>${button('Rotate invite code','rotate','','ghost full')}</div></div></div>`;
}
async function mutate(path,body={}){const serial=routeSerial,id=league.id;const r=await api(`/api/leagues/${id}/${path}`,body);if(serial!==routeSerial)return;notify(r.message||'Saved');closeModal();await route();}
function confirmAction(title,text,action,attrs=''){showModal(title,`<p class="muted">${text}</p>${button('Confirm','confirm-'+action,attrs,'primary full')}`);}
const actions={
create(){showModal('Create your league',`<form data-form="create">${field('name','League name','text','','required maxlength="100"')}<div class="form-grid">${field('max_teams','Maximum managers','number',8,'min="2" max="32" required')}${field('regular_weeks','Regular-season periods','number',6,'min="1" max="12" required')}${field('roster_size','FRC teams per manager','number',5,'min="1" max="12" required')}${field('starter_count','Scoring starters','number',3,'min="1" max="12" required')}${select('preset','Scoring template',option('standard','Standard')+option('half_ppr','Half PPR · +0.5 per cycle')+option('ppr','Full PPR · +1 per cycle'))}${select('playoff_teams','Playoffs',option(0,'None · regular-season standings')+option(4,'Top 4 · semifinals + final'))}</div><p class="muted">Season structure is fixed at creation. Scoring can be tuned before the first period opens. A random invite code will be ready to share.</p><button class="primary full">Create league</button></form>`);},
join(){showModal('Join a private league',`<form data-form="join">${field('code','12-character invite code','text','','required pattern="[a-fA-F0-9]{12}" minlength="12" maxlength="12" placeholder="A7C9E2B4D6F8" autocomplete="off"')}<p class="muted">Ask your commissioner for the code. Joining closes when the draft starts.</p><button class="primary full">Join league</button></form>`);},
invite(){showModal('Invite your friends',`<p class="muted">Share this code. Friends can sign in and choose “Join a league.”</p><p class="code">${esc(league.invite_code)}</p>${button('Copy invite code','copy-invite','','primary full')}<p class="muted">${league.member_count} / ${league.max_teams} managers · Joining ${league.draft_status==='PRE_DRAFT'?'open':'closed'}</p>`);},
async 'copy-invite'(){await navigator.clipboard.writeText(league.invite_code);notify('Invite code copied');},
refresh(){return route();},theme(el){theme(el.dataset.themeChoice);updateThemeSelection();},
rename(){showModal('Name your fantasy team',`<form data-form="rename">${field('name','Team name','text',mine().name,'required maxlength="100"')}<button class="primary full">Save team name</button></form>`);},
'start-draft'(){confirmAction('Start the snake draft?',`This closes joining and randomizes the order for ${league.member_count} managers. Each will draft ${league.roster_size} FRC teams. The draft cannot be reset. Ensure every manager is ready.`,'start-draft');},
'confirm-start-draft'(){return mutate('draft/start');},
async 'pick-team'(el){const r=await api('/api/leagues/draft',{league_id:league.id,team_number:Number(el.dataset.number)});notify(r.message);await route();},
watch(el){return mutate('watchlist',{team_number:Number(el.dataset.number)});},
claim(el){showModal(`Claim FRC ${el.dataset.number}`,`<form data-form="claim"><input type="hidden" name="team_number" value="${el.dataset.number}">${select('drop_team_number','Team to drop (required if roster is full)',option('','Use open roster spot')+mine().teams.map(t=>option(t.number,`FRC ${t.number} · ${t.position}`)).join(''))}<p class="muted">The commissioner processes claims between periods using rolling priority.</p><button class="primary full">Submit claim</button></form>`);},
drop(el){confirmAction(`Drop FRC ${el.dataset.number}?`,'This team becomes available to other managers through waivers. An empty starter slot scores zero.','drop',`data-number="${el.dataset.number}"`);},
'confirm-drop'(el){return mutate('drop',{team_number:Number(el.dataset.number)});},
'cancel-claim'(el){return mutate(`claims/${el.dataset.id}/cancel`);},
trade(){const others=league.rosters.filter(r=>r.id!==league.my_roster_id);showModal('Propose a trade',`<form data-form="trade">${select('receiver_id','Trade partner',others.map(r=>option(r.id,r.name)).join(''))}${select('give_number','FRC team you give',mine().teams.map(t=>option(t.number,`FRC ${t.number}`)).join(''))}${select('receive_number','FRC team you receive',(others[0]?.teams||[]).map(t=>option(t.number,`FRC ${t.number}`)).join(''))}<p class="muted">One-for-one offers require the receiving manager to accept.</p><button class="primary full">Send trade offer</button></form>`);},
 'trade-decision'(el){if(el.dataset.decision==='accept'){confirmAction('Accept this trade?','The teams will exchange rosters immediately.','trade',`data-id="${el.dataset.id}"`);return;}return mutate(`trades/${el.dataset.id}`,{action:el.dataset.decision});},
'confirm-trade'(el){return mutate(`trades/${el.dataset.id}`,{action:'accept'});},
'process-waivers'(){confirmAction('Process pending claims?','Claims resolve in rolling priority order. Successful roster changes take effect immediately.','waivers');},
'confirm-waivers'(){return mutate('waivers/process');},
rotate(){confirmAction('Rotate invite code?','The old code will stop working immediately. Existing memberships remain.','rotate');},
'confirm-rotate'(){return mutate('invite/rotate');},
'open-period'(el){confirmAction(`Open period ${el.dataset.week}?`,'Starter lineups freeze now. Lineup changes, trades, waivers, and drops lock until finalization.','open',`data-week="${el.dataset.week}"`);},
'confirm-open'(el){return mutate(`periods/${el.dataset.week}/open`);},
async finalize(el){const currentLeague=league,serial=routeSerial;const records=await api(`/api/leagues/${currentLeague.id}/periods/${el.dataset.week}/scores`);if(serial!==routeSerial||league?.id!==currentLeague.id)return;const recorded=new Set(records.map(r=>r.team_number));const missing=league.rosters.flatMap(r=>r.teams.filter(t=>t.position==='STARTER'&&!recorded.has(t.number)).map(t=>t.number));confirmAction(`Finalize period ${el.dataset.week}?`,`Imported robot match records: ${records.length}. ${missing.length?`Starters without records: ${missing.join(', ')}; these score zero. `:''}Review all matches and corrections first. Finalization is permanent and may advance playoff rounds.`,'finalize',`data-week="${el.dataset.week}"`);},
'confirm-finalize'(el){return mutate(`periods/${el.dataset.week}/finalize`);},
import(el){const sample=JSON.stringify({rules_version:league.scoring.version,records:[{match_key:'event_qm1',team_number:254,metrics:{auto:0,teleop:0,endgame:0,cycles:0,win:0,fouls:0}}]},null,2);showModal(`Import period ${el.dataset.week} results`,`<p class="muted">Paste normalized robot-level results. Reimporting a match/team replaces the prior record. Include every metric with a nonzero weight and the matching rules version.</p><form data-form="import" data-week="${el.dataset.week}"><label>Normalized JSON<textarea name="json" rows="12" required spellcheck="false" placeholder="${esc(sample)}"></textarea></label><p class="muted">The example is a zero-value format guide, not real results. Only import verified data.</p><button class="primary full">Validate & import</button></form>`);},
'remove-score'(el){confirmAction('Remove incorrect match record?','This removes the selected robot observation and recalculates provisional scores. Finalized periods cannot be changed.','remove-score',`data-week="${el.dataset.week}" data-id="${el.dataset.id}"`);},
async 'confirm-remove-score'(el){const r=await api(`/api/leagues/${league.id}/periods/${el.dataset.week}/scores/${el.dataset.id}`,{},'DELETE');notify(r.message);closeModal();await route();},
async 'score-detail'(el){const currentLeague=league,serial=routeSerial;const rows=await api(`/api/leagues/${currentLeague.id}/periods/${el.dataset.week}/scores`);if(serial!==routeSerial||league?.id!==currentLeague.id)return;showModal(`Period ${el.dataset.week} · Robot points`,rows.length?`<p class="muted">Per-match points before averaging or summing over the period.</p><div class="table-wrap"><table><thead><tr><th>Match</th><th>Robot</th><th>Points</th><th>Correction</th><th>Metrics</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.match_key)}</td><td>${r.team_number}</td><td>${r.points}</td><td>${owner()&&league.periods.find(p=>p.week===Number(el.dataset.week))?.status==='OPEN'?button('Remove incorrect record','remove-score',`data-week="${el.dataset.week}" data-id="${r.id}"`):''}</td><td>${esc(Object.entries(r.metrics).map(([k,v])=>`${k}: ${v}`).join(' · '))}</td></tr>`).join('')}</tbody></table></div>`:empty('No match records','Your commissioner can import played-match results into an open period.'));}
};
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=actions[el.dataset.action];if(!action)return;el.disabled=true;try{await action(el);}catch(error){if($('modal').open)$('dialogStatus').textContent=error.message;else notify(error.message,true);}finally{el.disabled=false;}});
document.addEventListener('change',event=>{if(event.target.name!=='receiver_id')return;const roster=league.rosters.find(r=>r.id===Number(event.target.value));event.target.form.elements.receive_number.innerHTML=(roster?.teams||[]).map(t=>option(t.number,`FRC ${t.number}`)).join('');});
const forms={
'proxy-pick'(form){return mutate('draft/commissioner-pick',{team_number:Number(formValue(form,'team_number'))});},
async create(form){const data=Object.fromEntries(new FormData(form));for(const k of ['max_teams','regular_weeks','roster_size','starter_count','playoff_teams'])data[k]=Number(data[k]);const r=await api('/api/leagues/create',data);closeModal();location.hash=`league/${r.league_id}/home`;notify('League created. Your invite code is ready to share.');},
async join(form){const r=await api('/api/leagues/join',{code:formValue(form,'code').trim().toUpperCase()});closeModal();location.hash=`league/${r.league_id}/home`;notify('You joined the league.');},
rename(form){return mutate('team-name',{name:formValue(form,'name')});},
lineup(form){return mutate('lineup',{starters:new FormData(form).getAll('starters').map(Number)});},
async pick(form){const r=await api('/api/leagues/draft',{league_id:league.id,team_number:Number(formValue(form,'team_number'))});notify(r.message);await route();},
claim(form){const drop=formValue(form,'drop_team_number');return mutate('claims',{team_number:Number(formValue(form,'team_number')),drop_team_number:drop?Number(drop):null});},
trade(form){return mutate('trades',Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,Number(v)])));},
message(form){return mutate('messages',{text:formValue(form,'text')});},
scoring(form){const d=new FormData(form);return mutate('scoring',{version:d.get('version'),aggregation:d.get('aggregation'),active:d.has('active'),weights:Object.fromEntries(Object.keys(metricLabels).map(k=>[k,Number(d.get(k))]))});},
import(form){let d;try{d=JSON.parse(formValue(form,'json'));}catch{throw new Error('Invalid JSON. Check quotes, commas, and brackets.');}return mutate(`periods/${form.dataset.week}/import`,d);},
search(form){scoutQuery=formValue(form,'search').trim().toLowerCase();scoutFilter=formValue(form,'filter');$('playerResults').innerHTML=playerRows(scoutTeams());}
};
document.addEventListener('submit',async event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();if(form.dataset.busy)return;form.dataset.busy='true';const buttons=form.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await forms[form.dataset.form](form);}catch(error){if($('modal').open)$('dialogStatus').textContent=error.message;else notify(error.message,true);}finally{delete form.dataset.busy;buttons.forEach(b=>b.disabled=false);}});
$('authForm').addEventListener('submit',async event=>{event.preventDefault();if($('authSubmit').disabled)return;$('authSubmit').disabled=true;$('authStatus').textContent='Signing in…';try{const username=$('username').value.trim(),password=$('password').value;let d;if(registerMode)d=await api('/api/auth/register',{username,password});else{const r=await fetch('/api/auth/login',{method:'POST',body:new URLSearchParams({username,password})});d=await r.json();if(!r.ok)throw new Error(d.detail||'Sign-in failed');}signedIn(d);$('authStatus').textContent='';}catch(error){$('authStatus').textContent=error.message;}finally{$('authSubmit').disabled=false;}});
$('authToggle').addEventListener('click',()=>{registerMode=!registerMode;$('authTitle').textContent=registerMode?'Create your account':'Sign in to your leagues';$('authSubmit').textContent=registerMode?'Create account':'Sign in';$('authToggle').textContent=registerMode?'Already have an account? Sign in':'New here? Create an account';$('password').autocomplete=registerMode?'new-password':'current-password';$('authStatus').textContent='';});
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();$('main').focus();});
$('closeModal').addEventListener('click',closeModal);$('logoutButton').addEventListener('click',logout);$('profileButton').addEventListener('click',()=>location.hash='profile');
$('rulesLink').addEventListener('click',event=>{event.preventDefault();if(league){location.hash=leaguePath('scoring');return;}showModal('Fantasy FRC scoring','<p>Leagues choose production weights, win bonuses, and foul deductions. Half and full PPR templates add points per completed scoring cycle. Starter robot match points are averaged or summed over a period.</p><p class="muted">BIOCORE templates remain provisional until the commissioner reviews the released game and activates season rules.</p>');});
window.addEventListener('hashchange',route);const savedTheme=storage.get('frc_theme');theme(themes.some(t=>t.id===savedTheme)?savedTheme:'default');route();
const accountToken=token;
if(accountToken&&user) api('/api/auth/me').then(data=>{if(token!==accountToken)return;user=data;storage.set('frc_user',JSON.stringify(user));route();}).catch(error=>notify(error.message,true));
$('adminButton').onclick=()=>{location.hash='admin';};
fetch('/api/auth/config').then(r=>r.json()).then(config=>{if(!config.google_client_id)return;const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=()=>{google.accounts.id.initialize({client_id:config.google_client_id,callback:async response=>{try{signedIn(await api('/api/auth/google',{credential:response.credential}));}catch(error){$('authStatus').textContent=error.message;}}});google.accounts.id.renderButton($('googleButton'),{theme:'outline',size:'large'});};document.head.appendChild(script);}).catch(()=>{});
